import type postgres from "postgres";
import { sql } from "./db";
import { HttpError } from "./errors";
import { coerce } from "./coerce";
import { authorize, availableTransitions, decideTransition, entityByTable, readScope } from "./guard";
import { registry } from "./registry";
import type { EntityDef, Row, User } from "./types";

type Tx = postgres.TransactionSql;
type Change = { entityId: string; before: Row | null; after: Row | null };

export async function withAudit<T>(
  actor: string,
  entity: EntityDef,
  action: string,
  change: (tx: Tx) => Promise<Change & { result: T }>,
): Promise<T> {
  return (await sql.begin(async (tx) => {
    const c = await change(tx);
    if (registry.audit.enabled)
      await tx`insert into audit_events (actor, entity, entity_id, action, before, after)
        values (${actor}, ${entity.entity}, ${c.entityId}, ${action}, ${tx.json(c.before as postgres.JSONValue)}, ${tx.json(c.after as postgres.JSONValue)})`;
    return c.result;
  })) as T;
}

function resolve(table: string): EntityDef {
  const e = entityByTable(table);
  if (!e) throw new HttpError(404, `unknown entity '${table}'`);
  return e;
}

const plain = (row: postgres.Row): Row => JSON.parse(JSON.stringify(row)) as Row;

async function load(tx: Tx | postgres.Sql, entity: EntityDef, id: string, lock = false): Promise<Row | null> {
  if (!/^[0-9a-f-]{36}$/i.test(id)) return null;
  const rows = lock
    ? await tx`select * from ${tx(entity.table)} where id = ${id} for update`
    : await tx`select * from ${tx(entity.table)} where id = ${id}`;
  return rows[0] ? plain(rows[0]) : null;
}

export async function list(user: User, table: string): Promise<Row[]> {
  const entity = resolve(table);
  const scope = readScope(user, entity);
  if (!scope) throw new HttpError(403, `cannot read ${entity.entity}`);
  const rows =
    scope === "all"
      ? await sql`select * from ${sql(entity.table)} order by created_at desc, id`
      : await sql`select * from ${sql(entity.table)} where created_by = ${user.email} order by created_at desc, id`;
  return rows.map(plain);
}

export async function get(user: User, table: string, id: string): Promise<Row> {
  const entity = resolve(table);
  const row = await load(sql, entity, id);
  if (!row || !authorize(user, entity, "read", row)) throw new HttpError(404, "not found");
  return row;
}

function valuesOrThrow(entity: EntityDef, input: Record<string, unknown>, mode: "create" | "update") {
  const r = coerce(entity, input, mode);
  if (!r.ok) throw new HttpError(422, r.errors.join("; "));
  return r.values;
}

export async function create(user: User, table: string, input: Record<string, unknown>): Promise<Row> {
  const entity = resolve(table);
  if (!authorize(user, entity, "create")) throw new HttpError(403, `cannot create ${entity.entity}`);
  const values = { ...valuesOrThrow(entity, input, "create"), created_by: user.email };
  return withAudit(user.email, entity, "create", async (tx) => {
    const [row] =
      await tx`insert into ${tx(entity.table)} ${tx(values as Record<string, postgres.SerializableParameter>)} returning *`;
    const after = plain(row);
    return { entityId: after.id, before: null, after, result: after };
  });
}

export async function update(user: User, table: string, id: string, input: Record<string, unknown>): Promise<Row> {
  const entity = resolve(table);
  const values = valuesOrThrow(entity, input, "update");
  return withAudit(user.email, entity, "update", async (tx) => {
    const before = await load(tx, entity, id, true);
    if (!before || !authorize(user, entity, "read", before)) throw new HttpError(404, "not found");
    if (!authorize(user, entity, "update", before)) throw new HttpError(403, `cannot update this ${entity.entity}`);
    const [row] =
      await tx`update ${tx(entity.table)} set ${tx({ ...values, updated_at: new Date() } as Record<string, postgres.SerializableParameter>)} where id = ${id} returning *`;
    const after = plain(row);
    return { entityId: id, before, after, result: after };
  });
}

export async function remove(user: User, table: string, id: string): Promise<void> {
  const entity = resolve(table);
  await withAudit(user.email, entity, "delete", async (tx) => {
    const before = await load(tx, entity, id, true);
    if (!before || !authorize(user, entity, "read", before)) throw new HttpError(404, "not found");
    if (!authorize(user, entity, "delete", before)) throw new HttpError(403, `cannot delete this ${entity.entity}`);
    await tx`delete from ${tx(entity.table)} where id = ${id}`;
    return { entityId: id, before, after: null, result: undefined };
  });
}

export async function transition(
  user: User,
  table: string,
  id: string,
  transitionId: string,
  input: Record<string, unknown> = {},
): Promise<Row> {
  const entity = resolve(table);
  const workflow = entity.workflow;
  if (!workflow) throw new HttpError(404, `${entity.entity} has no workflow`);
  const values = valuesOrThrow(entity, input, "update");
  return withAudit(user.email, entity, `transition:${transitionId}`, async (tx) => {
    const before = await load(tx, entity, id, true);
    if (!before) throw new HttpError(404, "not found");
    const d = decideTransition(user, entity, before, transitionId, { ...before, ...values });
    if (!d.ok) throw new HttpError(d.status, d.reason);
    const set = { ...values, [workflow.field]: d.transition.to, updated_at: new Date() };
    const [row] =
      await tx`update ${tx(entity.table)} set ${tx(set as Record<string, postgres.SerializableParameter>)} where id = ${id} returning *`;
    const after = plain(row);
    return { entityId: id, before, after, result: after };
  });
}

export async function inbox(user: User): Promise<{ entity: EntityDef; row: Row }[]> {
  const out: { entity: EntityDef; row: Row }[] = [];
  for (const entity of registry.entities) {
    if (!entity.workflow || !readScope(user, entity)) continue;
    for (const row of await list(user, entity.table))
      if (availableTransitions(user, entity, row).length) out.push({ entity, row });
  }
  return out;
}

export async function auditLog(user: User, limit = 200): Promise<Row[]> {
  if (!user.roles.includes("admin")) throw new HttpError(403, "the audit log is for admins");
  return (await sql`select * from audit_events order by id desc limit ${limit}`).map(plain);
}
